set-variable.value:
@{
            var model = (string)context.Variables["requested-model"];
            switch (model) {
%{ for model_name, deployment_name in model_routing ~}
                case "${model_name}": return "${deployment_name}";
%{ endfor ~}
                default: return "";
            }
        }

policies.on-error:

%{ if enable_content_safety ~}





                        application/json


                        @(context.RequestId.ToString())

                    @(new JObject(new JProperty("error", new JObject(new JProperty("message", "Request blocked by content safety policy."), new JProperty("type", "invalid_request_error"), new JProperty("code", "content_filtered")))).ToString())



%{ endif ~}
